function fmtDate(v){if(!v)return'—';const d=new Date(v);return d.toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:d.getFullYear()!==new Date().getFullYear()?'2-digit':undefined,hour:'2-digit',minute:'2-digit'})}
