  text=text.replace(/(^|[^\\])~([^~\n]+)~/g,'$1<del>$2</del>');
  text=text.replace(/\\([*_~`])/g,'$1');
  text=text.replace(/§§BCLINK(\d+)§§/g,(_,i)=>links[Number(i)]||'');
  text=text.replace(/§§BCCODE(\d+)§§/g,(_,i)=>code[Number(i)]||'');
