    if(/^>\s?/.test(line))return `<div class="wa-quote">${whatsappInlineHtml(line.replace(/^>\s?/,''))}</div>`;
    if(/^[-*]\s+/.test(line))return `<div class="wa-list-line"><span>•</span><div>${whatsappInlineHtml(line.replace(/^[-*]\s+/,''))}</div></div>`;
